<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Teacher'],true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}
$student=filter_var($_POST['student_id']??null,FILTER_VALIDATE_INT);$date=trim((string)($_POST['incident_on']??''));$category=(string)($_POST['category']??'');$severity=(string)($_POST['severity']??'');$description=trim((string)($_POST['description']??''));$action=trim((string)($_POST['immediate_action']??''));$dateObj=DateTimeImmutable::createFromFormat('!Y-m-d',$date);$dateErrors=DateTimeImmutable::getLastErrors();$categories=['Discipline','Bullying','Attendance','Wellbeing','Safety','Property damage','Academic integrity','Other'];$severities=['Low','Moderate','High','Critical'];
if(!$student||$dateObj===false||$dateObj->format('Y-m-d')!==$date||($dateErrors!==false&&($dateErrors['warning_count']||$dateErrors['error_count']))||$date>date('Y-m-d')||!in_array($category,$categories,true)||!in_array($severity,$severities,true)||strlen($description)<8||strlen($description)>5000||strlen($action)>2000){$_SESSION['error']='Check the incident date, category, severity and report details. The report must be at least 8 characters and no more than 5,000.';header('Location: ../?page=welfare');exit;}
$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT id,form_level,stream,status FROM students WHERE id=:id FOR UPDATE");$q->execute(['id'=>$student]);$learner=$q->fetch();if(!$learner)throw new DomainException('Learner record not found.');if($user['role']==='Teacher'){$year=(int)substr($date,0,4);$scope=$pdo->prepare("SELECT EXISTS(SELECT 1 FROM class_groups cg WHERE cg.academic_year=:year AND cg.form_level=:form AND cg.stream=COALESCE(:stream,'') AND (cg.class_teacher_id=:class_teacher OR EXISTS(SELECT 1 FROM class_subjects cs WHERE cs.class_id=cg.id AND cs.teacher_id=:subject_teacher)))");$scope->execute(['year'=>$year,'form'=>$learner['form_level'],'stream'=>$learner['stream'],'class_teacher'=>$user['id'],'subject_teacher'=>$user['id']]);if(!(int)$scope->fetchColumn()||$learner['status']!=='Active')throw new DomainException('You can report only on an active learner in a class assigned to you.');}
$q=$pdo->prepare('INSERT INTO student_incidents(student_id,incident_on,category,severity,description,immediate_action,reported_by) VALUES(:student,:date,:category,:severity,:description,:action,:user)');$q->execute(['student'=>$student,'date'=>$date,'category'=>$category,'severity'=>$severity,'description'=>$description,'action'=>$action?:null,'user'=>$user['id']]);$id=(int)$pdo->lastInsertId();audit_log('welfare.incident_reported','student_incidents',$id,['category'=>$category,'severity'=>$severity,'incident_on'=>$date]);$pdo->commit();$_SESSION['notice']='Confidential report submitted to school leadership.';}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Incident report save failed: '.$e->getMessage());$_SESSION['error']='Could not save the confidential report. No incident record was created.';}header('Location: ../?page=welfare');exit;
